#!/usr/bin/env python3
"""Feasibility-only replay on an unmodified Wormhole message trace.

This is not a paper experiment. It asks a narrower gate question: when real
message arrivals are bursty and chains share an audit budget, can an online
hint-aware scheduler outperform strong static-sqrt and max-age baselines
without injecting failures into the workload?
"""

from __future__ import annotations

